// Bubble swarm in a flotation cell: rising bubbles, the liquid flow each one sets up, and synthetic turbulence.
// Theoretical model only: the default swarm is generated by the program from published correlations.
// A tracks file can be loaded in the page; it is read in the browser and never stored or sent anywhere.
// Pure functions, no DOM. SI units inside, except where a name ends in Mm (millimetres).
'use strict';

// Water at 20 C and air. Surface tension 72.75 mN/m: Vargaftik, Volkov and Voljak (1983).
// Kolmogorov constant of the three-dimensional spectrum from the one-dimensional one, C1 = 0.53
// (Sreenivasan 1995), through C1 = (18/55) C for isotropic turbulence.
const SW = { g: 9.81, rhoL: 998.2, rhoG: 1.2, mu: 1.002e-3, sigma: 0.07275, C1: 0.53 };
SW.CK = SW.C1 * 55 / 18;

// Small random number generator (mulberry32), so a swarm can be made again from its seed.
function swRandom(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---------- single bubble: drag, rise speed and shape ----------
// Eotvos number with the volume-equivalent diameter d; sigma in N/m, water if not given.
const eotvos = (d, sigma) => SW.g * (SW.rhoL - SW.rhoG) * d * d / (sigma || SW.sigma);
// Drag coefficient of Tomiyama, Kataoka, Zun and Sakaguchi (1998) for a pure, slightly or fully contaminated system.
function cdTomiyama(Re, Eo, sys) {
  const shape = 8 / 3 * Eo / (Eo + 4);
  const sn = 1 + 0.15 * Math.pow(Re, 0.687);
  if (sys === 'pure') return Math.max(Math.min(16 / Re * sn, 48 / Re), shape);
  if (sys === 'full') return Math.max(24 / Re * sn, shape);
  return Math.max(Math.min(24 / Re * sn, 72 / Re), shape);    // slightly contaminated
}
// Terminal rise speed from the force balance (rhoL - rhoG) g pi d^3 / 6 = Cd rhoL U^2 pi d^2 / 8, by bisection.
function riseVelocity(d, sys, mu, sigma) {
  mu = mu || SW.mu;
  const Eo = eotvos(d, sigma);
  const F = (U) => U * U - 4 * (SW.rhoL - SW.rhoG) * SW.g * d / (3 * cdTomiyama(SW.rhoL * U * d / mu, Eo, sys) * SW.rhoL);
  let lo = 1e-9, hi = 10;
  for (let i = 0; i < 200; i++) { const m = Math.sqrt(lo * hi); if (F(m) > 0) hi = m; else lo = m; }
  return Math.sqrt(lo * hi);
}
// Aspect ratio (minor / major axis) of Wellek, Agrawal and Skelland (1966), for contaminated systems.
const aspectWellek = (Eo) => 1 / (1 + 0.163 * Math.pow(Eo, 0.757));
// Semi-axes of an oblate spheroid with the volume of a sphere of diameter d and aspect ratio E.
function semiAxes(d, E) {
  const r = d / 2;
  return { a: r * Math.pow(E, -1 / 3), c: r * Math.pow(E, 2 / 3) };
}

// ---------- the swarm ----------
// A bubble: x, y, z (mm, y upwards), velocity vx, vy, vz (m/s), semi-axes a (horizontal) and c (vertical) in mm,
// tilt alpha in degrees (rotation of the a axis from the x axis towards y).
// makeSwarm places n bubbles of diameter d (m) at random in a box (mm) without overlap, or, with o.chain, in a
// vertical line at x = z = 0 spaced o.spacing mm apart, as above a single needle. Each rises at its terminal speed.
function makeSwarm(o) {
  const rand = swRandom(o.seed || 1);
  const d = o.d, U = riseVelocity(d, o.sys, SW.mu, o.sigma), Eo = eotvos(d, o.sigma), E = aspectWellek(Eo), ax = semiAxes(d, E);
  const aMm = ax.a * 1e3, cMm = ax.c * 1e3;
  const [Lx, Ly, Lz] = o.box;
  const out = [];
  if (o.chain) {
    const sp = Math.max(o.spacing, 2.1 * cMm);
    for (let y = -Ly / 2 + sp / 2; y < Ly / 2 && out.length < o.n; y += sp) out.push({ id: out.length + 1, x: 0, y, z: 0, vx: 0, vy: U, vz: 0, a: aMm, c: cMm, alpha: 0 });
  }
  for (let tries = 0; !o.chain && out.length < o.n && tries < 200 * o.n; tries++) {
    const b = { id: out.length + 1, x: (rand() - 0.5) * Lx, y: (rand() - 0.5) * Ly, z: (rand() - 0.5) * Lz, vx: 0, vy: U, vz: 0, a: aMm, c: cMm, alpha: 0 };
    if (out.every((q) => Math.hypot(q.x - b.x, q.y - b.y, q.z - b.z) > 2.1 * aMm)) out.push(b);
  }
  return { bubbles: out, U, Eo, E, Re: SW.rhoL * U * d / SW.mu, a: aMm, c: cMm };
}

// Is the point (mm) inside the bubble? The spheroid's axis of symmetry is tilted in the x-y plane.
function insideBubble(b, x, y, z) {
  const t = b.alpha * Math.PI / 180, dx = x - b.x, dy = y - b.y, dz = z - b.z;
  const u = dx * Math.cos(t) + dy * Math.sin(t), v = -dx * Math.sin(t) + dy * Math.cos(t);
  return (u * u + dz * dz) / (b.a * b.a) + v * v / (b.c * b.c) < 1;
}
// Volume-equivalent radius in mm.
const eqRadiusMm = (b) => Math.cbrt(b.a * b.a * b.c);

// Liquid velocity (m/s) at a point (mm) from the bubbles: each bubble is a sphere of its volume-equivalent radius R
// moving with its velocity U through liquid at rest, which in potential flow gives the dipole field
//   u = (R^3 / (2 r^3)) (3 (U.n) n - U),   n = r / |r|        (Lamb 1932, Batchelor 1967)
// The fields of the bubbles are added. Returns null inside a bubble.
function bubbleFlow(bubbles, x, y, z) {
  let ux = 0, uy = 0, uz = 0;
  for (const b of bubbles) {
    if (insideBubble(b, x, y, z)) return null;
    const dx = x - b.x, dy = y - b.y, dz = z - b.z, r2 = dx * dx + dy * dy + dz * dz, r = Math.sqrt(r2);
    const R = eqRadiusMm(b);
    if (r < 0.5 * R) return null;
    const k = R * R * R / (2 * r2 * r);
    const nx = dx / r, ny = dy / r, nz = dz / r, un = b.vx * nx + b.vy * ny + b.vz * nz;
    ux += k * (3 * un * nx - b.vx); uy += k * (3 * un * ny - b.vy); uz += k * (3 * un * nz - b.vz);
  }
  return [ux, uy, uz];
}

// ---------- synthetic turbulence: kinematic simulation (Fung, Hunt, Malik and Perkins 1992), frozen in time ----------
//   u(x) = sum_n A_n cos(k_n . x) + B_n sin(k_n . x),   A_n, B_n perpendicular to k_n, so div u = 0
//   |A_n|^2 = |B_n|^2 = 2 E(k_n) dk_n,   so the mean kinetic energy is sum E(k_n) dk_n
//   E(k) = C eps^(2/3) k^(-5/3)  for 2 pi / L <= k <= k_max
// The wavenumbers are spaced geometrically; k_n is the geometric centre of band n.
function kolmogorovScale(eps, nu) { return Math.pow(nu * nu * nu / eps, 0.25); }
const spectrum = (k, eps) => SW.CK * Math.pow(eps, 2 / 3) * Math.pow(k, -5 / 3);
function makeTurbulence(o) {
  const rand = swRandom(o.seed || 7);
  const nu = SW.mu / SW.rhoL, eta = kolmogorovScale(o.eps, nu);
  const k1 = 2 * Math.PI / o.L, kN = Math.min(1 / eta, o.kmax || Infinity);
  const N = o.modes || 200, modes = [];
  let energy = 0;
  const unit = () => { const z = 2 * rand() - 1, p = 2 * Math.PI * rand(), s = Math.sqrt(1 - z * z); return [s * Math.cos(p), s * Math.sin(p), z]; };
  const perp = (khat) => {          // random unit vector perpendicular to khat
    const v = unit(), d = v[0] * khat[0] + v[1] * khat[1] + v[2] * khat[2];
    const w = [v[0] - d * khat[0], v[1] - d * khat[1], v[2] - d * khat[2]], m = Math.hypot(...w);
    return [w[0] / m, w[1] / m, w[2] / m];
  };
  for (let n = 0; n < N; n++) {
    const lo = k1 * Math.pow(kN / k1, n / N), hi = k1 * Math.pow(kN / k1, (n + 1) / N), k = Math.sqrt(lo * hi), dk = hi - lo;
    const amp = Math.sqrt(2 * spectrum(k, o.eps) * dk), khat = unit();
    const A = perp(khat), B = perp(khat);
    modes.push({ k: [k * khat[0], k * khat[1], k * khat[2]], A: A.map((c) => amp * c), B: B.map((c) => amp * c) });
    energy += spectrum(k, o.eps) * dk;
  }
  const exact = 1.5 * SW.CK * Math.pow(o.eps, 2 / 3) * (Math.pow(k1, -2 / 3) - Math.pow(kN, -2 / 3));
  const total = 1.5 * SW.CK * Math.pow(o.eps, 2 / 3) * Math.pow(k1, -2 / 3);   // all scales smaller than L
  return { modes, eta, k1, kN, energy, exact, total, uRms: Math.sqrt(2 * energy / 3) };
}
// Velocity (m/s) of the synthetic turbulence at a point given in metres.
function turbulentFlow(T, x, y, z) {
  let ux = 0, uy = 0, uz = 0;
  for (const m of T.modes) {
    const ph = m.k[0] * x + m.k[1] * y + m.k[2] * z, c = Math.cos(ph), s = Math.sin(ph);
    ux += m.A[0] * c + m.B[0] * s; uy += m.A[1] * c + m.B[1] * s; uz += m.A[2] * c + m.B[2] * s;
  }
  return [ux, uy, uz];
}

// Positions after a time t (s): every bubble moves with its velocity, and the box is periodic in y,
// so a bubble that leaves at the top comes back at the bottom.
function advanceSwarm(bubbles, t, Ly) {
  return bubbles.map((b) => {
    let y = b.y + b.vy * t * 1e3;
    y = ((y + Ly / 2) % Ly + Ly) % Ly - Ly / 2;
    return Object.assign({}, b, { x: b.x + b.vx * t * 1e3, y, z: b.z + b.vz * t * 1e3 });
  });
}

// ---------- tracks file ----------
// CSV with a header line and the columns TimeStep, ID, X, Y, Z, VX, VY, VZ, a, c, alpha
// (positions and semi-axes in mm, velocities in m/s, alpha in degrees). Other columns are ignored.
function parseTracks(text) {
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== '');
  if (lines.length < 2) throw new Error('the file has no data lines');
  const sep = lines[0].includes(';') && !lines[0].includes(',') ? ';' : ',';
  const head = lines[0].split(sep).map((s) => s.trim().replace(/^"|"$/g, ''));
  const need = ['TimeStep', 'ID', 'X', 'Y', 'Z', 'VX', 'VY', 'VZ', 'a', 'c', 'alpha'];
  const col = {};
  for (const n of need) {
    const i = head.indexOf(n);
    if (i < 0) throw new Error(`column ${n} is missing`);
    col[n] = i;
  }
  const steps = new Map();
  let bad = 0;
  for (let l = 1; l < lines.length; l++) {
    const f = lines[l].split(sep).map(Number);
    const g = (n) => f[col[n]];
    const b = { step: g('TimeStep'), id: g('ID'), x: g('X'), y: g('Y'), z: g('Z'), vx: g('VX'), vy: g('VY'), vz: g('VZ'), a: g('a'), c: g('c'), alpha: g('alpha') };
    if (!Object.values(b).every(Number.isFinite) || !(b.a > 0 && b.c > 0)) { bad++; continue; }
    if (!steps.has(b.step)) steps.set(b.step, []);
    steps.get(b.step).push(b);
  }
  if (!steps.size) throw new Error('no valid rows');
  const keys = [...steps.keys()].sort((p, q) => p - q);
  return { steps, keys, bad, rows: lines.length - 1 - bad };
}

// Tracks of a parsed file, one per ID, sorted by time step.
function tracksById(T) {
  const m = new Map();
  for (const k of T.keys) for (const b of T.steps.get(k)) { if (!m.has(b.id)) m.set(b.id, []); m.get(b.id).push(b); }
  return m;
}
// Time between two time steps (s), estimated from the data: vertical distance moved per step divided by the
// vertical velocity, median over all pairs of consecutive points of all tracks.
function trackTimeStep(tracks) {
  const r = [];
  for (const pts of tracks.values()) for (let i = 1; i < pts.length; i++) {
    const ds = pts[i].step - pts[i - 1].step, v = 0.5 * (pts[i].vy + pts[i - 1].vy);
    if (ds > 0 && Math.abs(v) > 1e-6) r.push((pts[i].y - pts[i - 1].y) * 1e-3 / ds / v);
  }
  r.sort((p, q) => p - q);
  return r.length ? r[Math.floor(r.length / 2)] : NaN;
}
// Statistics of one track: mean equivalent diameter (m), mean rise velocity (m/s), mean aspect ratio c/a,
// and the rms of the horizontal velocity about its mean (m/s).
function trackStats(pts) {
  const n = pts.length, mean = (f) => pts.reduce((s, b) => s + f(b), 0) / n;
  const d = mean((b) => 2 * eqRadiusMm(b)) * 1e-3, U = mean((b) => b.vy), E = mean((b) => b.c / b.a);
  const vx0 = mean((b) => b.vx), vz0 = mean((b) => b.vz);
  const vh = Math.sqrt(mean((b) => (b.vx - vx0) ** 2 + (b.vz - vz0) ** 2));
  return { n, d, U, E, vh };
}

if (typeof module !== 'undefined') {
  module.exports = { SW, swRandom, eotvos, cdTomiyama, riseVelocity, aspectWellek, semiAxes, makeSwarm, insideBubble, eqRadiusMm, bubbleFlow, kolmogorovScale, spectrum, makeTurbulence, turbulentFlow, parseTracks, advanceSwarm, tracksById, trackTimeStep, trackStats };
}
